import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {STLLoader} from 'three/addons/loaders/STLLoader.js';
import {STLExporter} from 'three/addons/exporters/STLExporter.js';
import {multiply4,transformPoint} from './reconstruction-core.js';
import {installAppleUI} from './apple-ui.js';

const $=id=>document.getElementById(id);
const palette={matrix_1:0x5799ae,matrix_2:0xc28a45};
const state={dataset:null,matrix:'matrix_1',frame:31,threshold:.5,probabilities:null,mode:'full',meshes:{},clouds:{},planes:{},paths:{},offsets:{},images:new Map(),probabilityCache:new Map(),loadId:0,frameId:0,playing:false,worker:null,previewStats:null,custom:null};
let ui,manifest,renderer,scene,camera,controls,root,grid,axes,texture,frameTextureCanvas,objectURL=null,toastTimer,resizeObserver,animationId;
const stlLoader=new STLLoader(), clock=new THREE.Clock();

function toast(text,error=false){if(ui){ui.toast(text,error);return;}clearTimeout(toastTimer);$('toast').textContent=text;$('toast').classList.toggle('error',error);$('toast').style.transform='translate(-50%, 0)';$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,error?9000:4500);}
function showLoading(show,text='Loading the reconstruction…'){$('viewer-loading').hidden=!show;$('loading-text').textContent=text;}
function saveBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function matrixKeys(){return state.matrix==='both'?['matrix_1','matrix_2']:[state.matrix];}
function matrixName(key){return key==='matrix_1'?'Matrix 1':key==='matrix_2'?'Matrix 2':'Matrix 1 + Matrix 2';}
function physicalBounds(){const box=new THREE.Box3();for(const mesh of Object.values(state.meshes))if(mesh.visible){mesh.updateWorldMatrix(true,false);box.expandByObject(mesh);}return box;}
function disposeObject(object){if(!object)return;object.parent?.remove(object);object.geometry?.dispose();if(Array.isArray(object.material))object.material.forEach(m=>m.dispose());else object.material?.dispose();}
function clearSceneModels(){for(const collection of ['meshes','clouds','planes','paths']){for(const obj of Object.values(state[collection]))disposeObject(obj);state[collection]={};}disposeObject(grid);disposeObject(axes);grid=null;axes=null;}
function material(key){return new THREE.MeshStandardMaterial({color:palette[key]||palette.matrix_1,roughness:.45,metalness:.12,side:THREE.DoubleSide,wireframe:$('wireframe').checked,transparent:true,opacity:Number($('opacity').value)});}

function applySceneAppearance(theme){const dark=theme==='dark';palette.matrix_1=dark?0x8ab5d5:0x5799ae;palette.matrix_2=dark?0xdead77:0xc28a45;if(!renderer)return;renderer.setClearColor(getComputedStyle(document.documentElement).getPropertyValue('--studio').trim());renderer.toneMappingExposure=dark?1.1:1;for(const group of ['meshes','clouds','paths'])for(const [key,object]of Object.entries(state[group]))object.material.color.setHex(palette[key]||palette.matrix_1);if(grid){const colors=grid.geometry.getAttribute('color'),color=new THREE.Color(dark?0x3d4352:0xd1d8e0);for(let i=0;i<colors.count;i++)colors.setXYZ(i,color.r,color.g,color.b);colors.needsUpdate=true;grid.material.transparent=true;grid.material.opacity=.65;}}

function setupRenderer(){
 try{
  renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});
  renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.setClearColor(0xf0f3f7);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
  renderer.domElement.setAttribute('aria-label','3D cortical reconstruction. Drag to orbit, scroll to zoom, right-drag to pan.');renderer.domElement.setAttribute('role','img');$('viewport').prepend(renderer.domElement);
  scene=new THREE.Scene();camera=new THREE.OrthographicCamera(-100,100,100,-100,.01,5000);camera.up.set(0,0,1);camera.position.set(130,-180,170);
  controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.autoRotateSpeed=.65;controls.enablePan=true;controls.minZoom=.08;controls.maxZoom=30;
  scene.add(new THREE.HemisphereLight(0xe9f0ff,0x515b73,1.65));
  const key=new THREE.DirectionalLight(0xffffff,2.5);key.position.set(40,-70,130);scene.add(key);
  const rim=new THREE.DirectionalLight(0xd4e7ff,1.8);rim.position.set(-60,70,40);scene.add(rim);
  const fill=new THREE.DirectionalLight(0xf6e8dc,.7);fill.position.set(100,30,-20);scene.add(fill);
  root=new THREE.Group();scene.add(root);
  frameTextureCanvas=document.createElement('canvas');frameTextureCanvas.width=254;frameTextureCanvas.height=512;
  texture=new THREE.CanvasTexture(frameTextureCanvas);texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=THREE.LinearFilter;
  resizeObserver=new ResizeObserver(resize);resizeObserver.observe($('viewport'));resize();
  let lastFrameTime=0;
  function animate(time){animationId=requestAnimationFrame(animate);const delta=Math.min(clock.getDelta(),.1);controls.update(delta);renderer.render(scene,camera);updateScale();if(state.playing&&time-lastFrameTime>125){lastFrameTime=time;state.frame=(state.frame+1)%64;updateFrame();}}
  animationId=requestAnimationFrame(animate);
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('webgl-fallback').hidden=false;toast('The graphics context was lost. Reload the page to restore the 3D viewer.',true);});
 }catch(error){$('webgl-fallback').hidden=false;showLoading(false);$('capture').disabled=true;$('fit-camera').disabled=true;toast('WebGL 2 could not start. Image playback and downloads remain available.',true);}
}

function resize(){if(!renderer)return;const {width,height}=$('viewport').getBoundingClientRect();if(width<1||height<1)return;renderer.setSize(width,height,false);const center=(camera.right+camera.left)/2,halfHeight=(camera.top-camera.bottom)/2;camera.left=center-halfHeight*width/height;camera.right=center+halfHeight*width/height;camera.updateProjectionMatrix();fitCamera();}
function fitCamera(preset=null){if(!renderer||!Object.keys(state.meshes).length)return;const box=physicalBounds();if(box.isEmpty())return;const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),distance=Math.max(size.length()*2,1);let direction;
 if(preset==='oblique'){direction=new THREE.Vector3(1,-1.4,1.2).normalize();camera.up.set(0,0,1);}else if(preset==='front'){direction=new THREE.Vector3(0,-1,0);camera.up.set(0,0,1);}else if(preset==='top'){direction=new THREE.Vector3(0,0,1);camera.up.set(0,1,0);}else if(preset==='side'){direction=new THREE.Vector3(1,0,0);camera.up.set(0,0,1);}else{direction=camera.position.clone().sub(controls.target).normalize();if(!Number.isFinite(direction.x)||direction.length()<.5)direction.set(1,-1.4,1.2).normalize();}
 camera.position.copy(center).addScaledVector(direction,distance);controls.target.copy(center);camera.near=.01;camera.far=distance*20;camera.lookAt(center);camera.updateMatrixWorld(true);
 const projected=new THREE.Box3();for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z])projected.expandByPoint(new THREE.Vector3(x,y,z).applyMatrix4(camera.matrixWorldInverse));
 const aspect=$('viewport').clientWidth/$('viewport').clientHeight,span=projected.getSize(new THREE.Vector3()),height=Math.max(span.y,span.x/aspect,.1)*1.25;
 camera.left=-height*aspect/2;camera.right=height*aspect/2;camera.top=height/2;camera.bottom=-height/2;camera.zoom=1;camera.updateProjectionMatrix();controls.update();
}
function updateScale(){if(!camera)return;const perPixel=(camera.right-camera.left)/(camera.zoom*$('viewport').clientWidth);let length=20;for(const candidate of [.01,.02,.05,.1,.2,.5,1,2,5,10,20,50,100,200,500,1000,2000])if(candidate/perPixel<=80)length=candidate;const width=length/perPixel;if(width>2&&width<300){$('scale-line').style.width=`${width}px`;$('scale-label').textContent=`${length} ${state.mode==='custom'?'units':'mm'}`;}}

async function loadGeometry(url){const response=await fetch(url);if(!response.ok)throw Error(`Surface could not be loaded (${response.status}).`);return parseSTL(await response.arrayBuffer());}
function parseSTL(buffer){if(buffer.byteLength>100*1024**2)throw Error('This STL exceeds the 100 MB browser limit.');if(buffer.byteLength<15)throw Error('This file is too small to be a valid STL.');if(buffer.byteLength>=84){const count=new DataView(buffer).getUint32(80,true),expected=84+count*50,header=new TextDecoder().decode(buffer.slice(0,256));if(expected===buffer.byteLength||!header.trimStart().startsWith('solid')){if(expected!==buffer.byteLength)throw Error('The binary STL triangle count does not match its file size.');if(count>2_000_000)throw Error('This STL exceeds the two-million-triangle viewer limit.');}}const geometry=stlLoader.parse(buffer),position=geometry.getAttribute('position');if(!position||position.count<3||position.count%3!==0)throw Error('No complete STL triangles were found.');if(position.count>6_000_000)throw Error('This STL exceeds the two-million-triangle viewer limit.');for(const v of position.array)if(!Number.isFinite(v))throw Error('The STL contains invalid vertex coordinates.');geometry.computeBoundingBox();geometry.computeBoundingSphere();if(geometry.boundingSphere.radius<1e-9)throw Error('The STL has no measurable extent.');return geometry;}

async function loadProbabilities(dataset){if(state.probabilityCache.has(dataset.id))return state.probabilityCache.get(dataset.id);if(!('DecompressionStream' in window))throw Error('This browser cannot decompress the preview data. Use a current Chrome, Edge or Firefox.');const n=dataset.display_frames*512*254,all=new Float32Array(n);await Promise.all(dataset.probability_chunks.map(async chunk=>{const r=await fetch(chunk.file);if(!r.ok)throw Error('A probability data chunk could not be loaded.');const bytes=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();if(bytes.byteLength!==chunk.uncompressed_bytes)throw Error('Incomplete probability data.');all.set(new Float32Array(bytes),chunk.start*512*254);}));state.probabilityCache.set(dataset.id,all);return all;}

async function selectCase(id){
 const token=++state.loadId;cancelReconstruction(false);pause();state.mode='full';state.custom=null;state.previewStats=null;state.probabilities=null;state.pointData={};state.frame=31;state.images=new Map();state.dataset=manifest.cases.find(c=>c.id===id);state.matrix='matrix_1';$('restore-full').hidden=true;$('restore-full').innerHTML='Return to full-sweep surface <span>↗</span>';$('reconstruct').disabled=true;document.body.classList.remove('custom-mode');
 for(const group of ['calibration-settings','preview-settings','timeline-description'])$(group).classList.remove('disabled-controls');$('source-note').textContent='Source pixels and tracking are preserved. The overlay is a model prediction, pending further human annotation.';
 document.querySelectorAll('[data-case]').forEach(b=>{b.classList.toggle('selected',b.dataset.case===id);b.setAttribute('aria-pressed',String(b.dataset.case===id));});
 updateMatrixButtons();if(renderer){clearSceneModels();const b=new THREE.Box3();for(const info of Object.values(state.dataset.meshes))b.union(new THREE.Box3(new THREE.Vector3(...info.bounds_mm[0]),new THREE.Vector3(...info.bounds_mm[1])));const center=b.getCenter(new THREE.Vector3());root.position.copy(center).multiplyScalar(-1);const side=Math.max(100,Math.ceil(b.getSize(new THREE.Vector3()).length()/10)*10);grid=new THREE.GridHelper(side,Math.round(side/10),0x3d5947,0x243c2c);grid.rotation.x=Math.PI/2;grid.position.set(center.x,center.y,b.min.z-8);grid.material.transparent=true;grid.material.opacity=.55;root.add(grid);axes=new THREE.AxesHelper(12);axes.position.set(b.min.x-5,b.min.y-5,b.min.z-8);root.add(axes);applySceneAppearance(ui.theme);}
 $('timeline-description').textContent=`64 display frames · ${state.dataset.eligible_frames} source frames · sweep ${id}`;buildFilmstrip();updateFrame();showLoading(true,'Loading the full-sweep surface…');
 const meshTask=renderer?Promise.all(['matrix_1','matrix_2'].map(async key=>{const geometry=await loadGeometry(state.dataset.meshes[key].file);if(token!==state.loadId){geometry.dispose();return;}const mesh=new THREE.Mesh(geometry,material(key));mesh.name=key;root.add(mesh);state.meshes[key]=mesh;})):Promise.resolve();
 const probabilityTask=loadProbabilities(state.dataset).then(prob=>{if(token!==state.loadId)return;state.probabilities=prob;if(renderer){buildClouds();buildPlanesAndPaths();}updateFrame();setReconstructEnabled();}).catch(e=>{if(token===state.loadId){toast(e.message,true);$('source-note').textContent='The probability maps are unavailable. Original images and full-sweep STL files remain available.';}});
 try{await meshTask;if(token!==state.loadId)return;updateVisibility();fitCamera();updateStats();showLoading(false);$('viewer-title').textContent='Cortical surface';$('surface-kind').textContent='FULL SWEEP';$('surface-caption').textContent='A reconstruction of predicted visible cortical echoes. It represents observed surfaces, not a filled anatomical bone.';updateSceneLabel();updateDownload();}catch(e){if(token===state.loadId){showLoading(false);toast(e.message,true);}}
 await probabilityTask;
}

function buildClouds(){if(!renderer||!state.probabilities)return;for(const key of ['matrix_1','matrix_2']){disposeObject(state.clouds[key]);state.pointData??={};if(!state.pointData[key]){const positions=[],probabilities=[],ends=[],calibration=state.dataset.calibrations[key].matrix_mm.flat();for(let f=0;f<64;f++){const frame=state.dataset.frames[f],m=multiply4(frame.pose_local_from_tool_mm.flat(),calibration),[sx,sy]=frame.spacing_xy_mm;for(let row=0;row<512;row+=2)for(let col=0;col<254;col+=2){const p=state.probabilities[f*512*254+row*254+col];if(p>.1){positions.push(...transformPoint(m,col*sx,row*sy));probabilities.push(p);}}ends.push(probabilities.length);}state.pointData[key]={positions:new Float32Array(positions),probabilities:new Float32Array(probabilities),ends};}const cached=state.pointData[key],vertices=[],offsets=[];let start=0;for(const end of cached.ends){for(let i=start;i<end;i++)if(cached.probabilities[i]>state.threshold)vertices.push(cached.positions[i*3],cached.positions[i*3+1],cached.positions[i*3+2]);offsets.push(vertices.length/3);start=end;}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geometry.setDrawRange(0,offsets[state.frame]);const points=new THREE.Points(geometry,new THREE.PointsMaterial({color:palette[key],size:1.6,sizeAttenuation:false,transparent:true,opacity:.85}));root.add(points);state.clouds[key]=points;state.offsets[key]=offsets;}updateVisibility();}
function buildPlanesAndPaths(){if(!renderer)return;for(const key of ['matrix_1','matrix_2']){disposeObject(state.planes[key]);disposeObject(state.paths[key]);const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(new Float32Array(12),3));geometry.setAttribute('uv',new THREE.Float32BufferAttribute([0,1,1,1,1,0,0,0],2));geometry.setIndex([0,1,2,0,2,3]);const plane=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide,transparent:true,opacity:.6,depthWrite:false}));plane.frustumCulled=false;root.add(plane);state.planes[key]=plane;const cal=state.dataset.calibrations[key].matrix_mm.flat(),centers=state.dataset.frames.map(f=>new THREE.Vector3(...transformPoint(multiply4(f.pose_local_from_tool_mm.flat(),cal),253*f.spacing_xy_mm[0]/2,511*f.spacing_xy_mm[1]/2)));const path=new THREE.Line(new THREE.BufferGeometry().setFromPoints(centers),new THREE.LineBasicMaterial({color:palette[key],transparent:true,opacity:.65}));root.add(path);state.paths[key]=path;}updateVisibility();}
function updateVisibility(){
 if(!renderer)return;
 const custom=state.mode==='custom';document.body.classList.toggle('custom-mode',custom);document.querySelector('.timeline-panel').inert=custom;$('calibration-settings').inert=custom;$('advanced-settings').inert=custom;
 document.querySelector('.source-heading h2').textContent=custom?'Independent STL':'Inside the sweep';
 const keys=custom?['custom']:matrixKeys();
 for(const [key,mesh]of Object.entries(state.meshes)){mesh.visible=keys.includes(key)&&$('show-surface').checked;mesh.material.wireframe=$('wireframe').checked;mesh.material.opacity=Number($('opacity').value)*(state.matrix==='both'?.75:1);mesh.material.depthWrite=mesh.material.opacity>.9;}
 for(const [key,obj]of Object.entries(state.clouds))obj.visible=!custom&&keys.includes(key)&&$('show-points').checked;
 for(const [key,obj]of Object.entries(state.planes))obj.visible=!custom&&keys.includes(key)&&$('show-plane').checked;
 for(const [key,obj]of Object.entries(state.paths))obj.visible=!custom&&keys.includes(key)&&$('show-path').checked;
 updateStats();
}
function updateMatrixButtons(){document.querySelectorAll('[data-matrix]').forEach(b=>{const yes=b.dataset.matrix===state.matrix;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});}
async function selectMatrix(key){if(state.mode==='custom')return;cancelReconstruction(false);if(state.mode==='preview'){await restoreFull();}state.matrix=key;updateMatrixButtons();updateVisibility();updateFrame();updateSceneLabel();updateDownload();setReconstructEnabled();}
function updateSceneLabel(){$('settings-context').textContent=state.mode==='custom'?'Local STL':`Sweep ${state.dataset.id}`;if(state.mode==='custom'){$('scene-label').textContent='Local STL · original model units';$('scene-dot').style.background='var(--mint)';return;}const detail=state.mode==='preview'?`${state.previewStats.voxel.toFixed(1)} mm · ${state.previewStats.sampleCount} frames`:'0.3 mm voxels';$('scene-label').textContent=`${matrixName(state.matrix)} · ${detail}`;$('scene-dot').style.background=state.matrix==='matrix_2'?'var(--amber)':'var(--mint)';}
function updateStats(){if(!renderer||!Object.keys(state.meshes).length)return;let triangles=0;const bounds=new THREE.Box3();for(const [key,mesh]of Object.entries(state.meshes))if((state.mode==='custom'&&key==='custom')||(state.mode!=='custom'&&matrixKeys().includes(key))){const p=mesh.geometry.getAttribute('position');triangles+=(mesh.geometry.index?.count||p.count)/3;mesh.geometry.computeBoundingBox();bounds.union(mesh.geometry.boundingBox);}const size=bounds.getSize(new THREE.Vector3());$('triangle-count').textContent=Math.round(triangles).toLocaleString('en-US');$('model-dimensions').textContent=`${size.x.toFixed(1)} × ${size.y.toFixed(1)} × ${size.z.toFixed(1)} ${state.mode==='custom'?'units':'mm'}`;}
function updateDownload(){if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null;}const a=$('download-stl');if(state.mode==='custom'){a.href=URL.createObjectURL(state.custom.file);objectURL=a.href;a.download=state.custom.file.name;a.onclick=null;}else if(state.mode==='preview'){a.href='#';a.download='';a.onclick=e=>{e.preventDefault();exportPreview();};}else{const key=state.matrix==='both'?'matrix_1':state.matrix;a.href=state.dataset.meshes[key].file;a.download=`SonoBox_${state.dataset.id}_${key}.stl`;a.onclick=state.matrix==='both'?e=>{e.preventDefault();openDetails('data');}:null;}}
function setReconstructEnabled(){$('reconstruct').disabled=!renderer||!state.probabilities||state.matrix==='both'||state.mode==='custom'||!!state.worker;$('reconstruct').title=state.matrix==='both'?'Choose a single matrix to reconstruct a preview.':'Fuse the sampled probability images in the browser.';}

function buildFilmstrip(){const strip=$('filmstrip');strip.replaceChildren();for(let n=0;n<8;n++){const position=Math.round(n*63/7),frame=state.dataset.frames[position],button=document.createElement('button'),image=document.createElement('img'),label=document.createElement('span');image.src=frame.image;image.alt='';image.loading='lazy';label.textContent=String(frame.index).padStart(6,'0');button.setAttribute('aria-label',`Show original frame ${frame.index}`);button.dataset.position=position;button.append(image,label);button.addEventListener('click',()=>{state.frame=position;updateFrame();});strip.append(button);}}
function getFrameImage(frame){if(state.images.has(frame.index))return state.images.get(frame.index);const promise=new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('The original ultrasound image could not be loaded.'));image.src=frame.image;});state.images.set(frame.index,promise);return promise;}
async function updateFrame(){if(!state.dataset||state.mode==='custom')return;const token=++state.frameId,frame=state.dataset.frames[state.frame];$('previous-frame').disabled=state.frame===0;$('next-frame').disabled=state.frame===63;$('frame-slider').value=state.frame;ui.updateRange($('frame-slider'));$('frame-position').textContent=`${String(state.frame+1).padStart(2,'0')} / 64`;$('original-frame').textContent=String(frame.index).padStart(6,'0');$('frame-time').textContent=`${(frame.timestamp_s-state.dataset.frames[0].timestamp_s).toFixed(2)} s`;for(const button of $('filmstrip').children)button.classList.toggle('active',Math.abs(Number(button.dataset.position)-state.frame)<5);if(renderer){for(const key of ['matrix_1','matrix_2']){const cloud=state.clouds[key];if(cloud)cloud.geometry.setDrawRange(0,state.offsets[key][state.frame]);const plane=state.planes[key];if(plane){const m=multiply4(frame.pose_local_from_tool_mm.flat(),state.dataset.calibrations[key].matrix_mm.flat()),sx=frame.spacing_xy_mm[0],sy=frame.spacing_xy_mm[1],p=plane.geometry.getAttribute('position');for(const [n,[x,y]]of [[0,[0,0]],[1,[253*sx,0]],[2,[253*sx,511*sy]],[3,[0,511*sy]]])p.setXYZ(n,...transformPoint(m,x,y));p.needsUpdate=true;plane.geometry.computeVertexNormals();}}}
 try{const image=await getFrameImage(frame);if(token!==state.frameId||state.mode==='custom')return;const ctx=$('source-image').getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const pixels=ctx.getImageData(0,0,254,512),rawCopy=renderer?new Uint8ClampedArray(pixels.data):null;const overlay=$('show-overlay').checked&&!!state.probabilities;const start=state.frame*512*254;for(let q=0;overlay&&q<512*254;q++){if(state.probabilities[start+q]>state.threshold){const k=q*4;pixels.data[k]=pixels.data[k]*.3+145*.7;pixels.data[k+1]=pixels.data[k+1]*.3+219*.7;pixels.data[k+2]=pixels.data[k+2]*.3+182*.7;}}ctx.putImageData(pixels,0,0);$('image-label').textContent=overlay?'ORIGINAL + PREDICTION':'ORIGINAL B-MODE';if(renderer){const planeCtx=frameTextureCanvas.getContext('2d');for(let q=0;q<512*254;q++)pixels.data[q*4+3]=rawCopy[q*4]>8?185:0;planeCtx.putImageData(pixels,0,0);texture.needsUpdate=true;}}
 catch(e){if(token===state.frameId)toast(e.message,true);}}
function pause(){state.playing=false;$('play-pause').setAttribute('aria-label','Play sweep');$('play-pause').innerHTML='<svg aria-hidden="true"><use href="#i-play"/></svg>';}

function cancelReconstruction(notify=true){if(state.worker){state.worker.terminate();state.worker=null;if(notify)toast('Preview reconstruction cancelled.');}$('reconstruction-progress').hidden=true;setReconstructEnabled();}
async function reconstruct(){if(!state.probabilities||state.matrix==='both'||!renderer)return;pause();cancelReconstruction(false);const worker=new Worker('./reconstruction-worker.js',{type:'module'});state.worker=worker;setReconstructEnabled();$('reconstruction-progress').hidden=false;$('progress-bar').value=0;$('progress-text').textContent='Preparing probability images…';const dataset=state.dataset,key=state.matrix,loadId=state.loadId;const voxel=Number($('voxel-size').value),sampleCount=Number($('sample-count').value),threshold=state.threshold;
 const fail=message=>{if(state.worker!==worker)return;state.worker=null;worker.terminate();$('reconstruction-progress').hidden=true;setReconstructEnabled();toast(message,true);};
 worker.onerror=e=>fail(`The preview could not finish: ${e.message||'worker error'}`);
 worker.onmessage=({data})=>{if(state.worker!==worker||loadId!==state.loadId)return;if(data.type==='progress'){$('progress-bar').value=data.progress*100;$('progress-text').textContent=data.text;}else if(data.type==='error'){fail(data.message);}else if(data.type==='complete'){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(data.position),3));geometry.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(data.normal),3));geometry.computeBoundingBox();geometry.computeBoundingSphere();for(const obj of Object.values(state.meshes))disposeObject(obj);state.meshes={};const mesh=new THREE.Mesh(geometry,material(key));root.add(mesh);state.meshes[key]=mesh;state.previewStats={...data.stats,matrix:key,sweep:dataset.id};state.mode='preview';state.worker=null;worker.terminate();$('reconstruction-progress').hidden=true;$('restore-full').hidden=false;$('surface-kind').textContent='BROWSER PREVIEW';$('surface-caption').textContent=`Computed from ${sampleCount} sampled frames at ${voxel.toFixed(1)} mm, p > ${threshold.toFixed(2)}. A coarser preview of the fusion process; the full-sweep export is separate.`;updateVisibility();updateSceneLabel();updateDownload();setReconstructEnabled();toast(`Preview reconstructed: ${data.stats.triangles.toLocaleString('en-US')} triangles in ${data.stats.seconds.toFixed(1)} s.`);}};
 worker.postMessage({probabilityBuffer:state.probabilities.buffer,frames:dataset.frames,calibration:dataset.calibrations[key].matrix_mm,width:254,height:512,voxel,threshold,sampleCount});
}
async function restoreFull(){if(state.mode==='custom'){await selectCase(state.dataset.id);return;}cancelReconstruction(false);const token=state.loadId;showLoading(true,'Restoring the full-sweep surfaces…');try{const result=await Promise.all(['matrix_1','matrix_2'].map(async key=>[key,await loadGeometry(state.dataset.meshes[key].file)]));if(token!==state.loadId){result.forEach(([,g])=>g.dispose());return;}for(const obj of Object.values(state.meshes))disposeObject(obj);state.meshes={};for(const [key,g]of result){const mesh=new THREE.Mesh(g,material(key));root.add(mesh);state.meshes[key]=mesh;}state.mode='full';state.previewStats=null;$('restore-full').hidden=true;$('surface-kind').textContent='FULL SWEEP';$('surface-caption').textContent='A reconstruction of predicted visible cortical echoes. It represents observed surfaces, not a filled anatomical bone.';updateVisibility();updateSceneLabel();updateDownload();}catch(e){toast(e.message,true);}finally{showLoading(false);setReconstructEnabled();}}
function exportPreview(){
 if(state.mode!=='preview')return;const source=state.meshes[state.matrix];if(!source)return;
 const mesh=new THREE.Mesh(source.geometry,new THREE.MeshBasicMaterial());mesh.updateMatrixWorld(true);
 const bytes=new STLExporter().parse(mesh,{binary:true});
 saveBlob(new Blob([bytes],{type:'application/octet-stream'}),`SonoBox_${state.dataset.id}_${state.matrix}_preview_${state.previewStats.voxel}mm.stl`);
 mesh.material.dispose();
}
function exportPreviewMetadata(){
 if(!state.previewStats)return;
 const key=state.previewStats.matrix,provenance={...state.previewStats,coordinate_system:manifest.coordinate_system,calibration:state.dataset.calibrations[key],source_mhd_sha256:state.dataset.source_mhd_sha256,checkpoint_sha256:state.dataset.checkpoint_sha256};
 saveBlob(new Blob([JSON.stringify(provenance,null,2)],{type:'application/json'}),`SonoBox_${state.dataset.id}_preview_provenance.json`);
}

async function openSTL(file){if(!file)return;if(!renderer){toast('STL viewing requires WebGL 2.',true);return;}if(!file.name.toLowerCase().endsWith('.stl')){toast('Choose an ASCII or binary .stl file.',true);return;}showLoading(true,'Opening your STL locally…');try{const geometry=parseSTL(await file.arrayBuffer());cancelReconstruction(false);pause();++state.loadId;++state.frameId;clearSceneModels();state.mode='custom';state.custom={file};const mesh=new THREE.Mesh(geometry,material('matrix_1'));root.add(mesh);state.meshes={custom:mesh};const center=geometry.boundingBox.getCenter(new THREE.Vector3());root.position.copy(center).multiplyScalar(-1);const size=geometry.boundingBox.getSize(new THREE.Vector3()).length();grid=new THREE.GridHelper(size*1.3,12,0x3d5947,0x243c2c);grid.rotation.x=Math.PI/2;grid.position.set(center.x,center.y,geometry.boundingBox.min.z-size*.1);root.add(grid);applySceneAppearance(ui.theme);$('viewer-title').textContent='STL explorer';$('surface-kind').textContent='LOCAL FILE';$('surface-caption').textContent=`${file.name} · STL does not encode units. Dimensions are shown in original model units; no upload is performed.`;$('restore-full').hidden=false;$('restore-full').innerHTML='Return to the ultrasound demo <span>↗</span>';$('source-note').textContent='Your STL is displayed locally. Select a sweep to return to its linked ultrasound images.';for(const id of ['calibration-settings','preview-settings'])$(id).classList.add('disabled-controls');document.querySelectorAll('[data-case]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});updateVisibility();fitCamera();updateStats();updateSceneLabel();updateDownload();setReconstructEnabled();toast('STL loaded locally. Its coordinates and model units are preserved.');}catch(e){toast(`Could not open STL: ${e.message}`,true);}finally{showLoading(false);}}

function openDetails(kind){const d=state.dataset;let html='';if(kind==='method')html=`<h2>From tracked frames to visible echoes.</h2><p>This demo uses the SonoBox reconstruction pipeline. The interaction is inspired by the <a href="http://apps.myluo.cn/RecON" target="_blank" rel="noopener noreferrer">RecON demonstration</a>; the tracking and reconstruction methods are different.</p><h3>1 · Ultrasound and tracking</h3><p>Each original 254 × 512 B-mode image has a recorded robot tool pose, timestamp and 0.157447 mm in-plane pixel spacing. Scrub the sequence to move the image plane through the scene. Playback shows 64 uniformly sampled original frames, with no image resizing in the source assets.</p><h3>2 · Predicted visible cortex</h3><p>The raw-B-mode 2D nnU-Net predicts a cortex probability for each pixel. These probability maps were computed offline; the page does not run the neural network. The green overlay and accumulated points show predicted echoes, not human reference labels. Points are sampled every second row and column for rendering.</p><h3>3 · Volume fusion</h3><p>The browser preview actually places every pixel of its selected probability images using the recorded poses and selected calibration. It accumulates probability-weighted and unit sampling weights with trilinear splatting, applies Gaussian smoothing (σ = 0.25 mm), then divides by support. Voxels below support 0.05 are excluded. Marching cubes extracts the selected probability isosurface.</p><p>Choose 16, 32 or 64 frames and a 0.8–2.0 mm grid. This preview uses fewer frames and a coarser grid than the full reconstruction, so gaps and surface details can differ. Its exported coordinates remain in the same physical local frame.</p><h3>4 · Full-sweep result</h3><p>The supplied full-sweep STLs use all ${d.eligible_frames} usable frames of sweep ${d.id}, 0.3 mm voxels, Gaussian σ = 0.25 mm, support ≥ 0.05 and probability ≥ 0.50. They are unchanged copies of the sealed research exports. These echo ribbons do not fill bone interiors and do not establish absolute 3D or calibration accuracy.</p><h3>Controls</h3><p>Drag to orbit, scroll to zoom and right-drag to pan. Front, top and side refer to the local coordinate frame, not verified anatomical directions. Turn on points or the scan trajectory to explore spatial placement. Open a local ASCII or binary STL to inspect your own model; the file stays in the browser.</p>`;
 else if(kind==='matrices')html=`<h2>Two supplied calibrations.</h2><p>Matrix 1 and Matrix 2 are the two fixed single-filament calibration results supplied with the project. Only translations are converted from metres to millimetres. This website does not fit or optimize either calibration.</p><p>Both surfaces and all image planes share the first usable tool frame within the current sweep. Compare overlays them in that common frame; they are not independently centered or registered.</p><pre>p_local = inverse(pose_first) × pose_i × calibration_mm\n          × [column × sx, row × sy, 0, 1]</pre>${['matrix_1','matrix_2'].map(key=>`<h3>${matrixName(key)} · translations in mm</h3><pre>${d.calibrations[key].matrix_mm.map(row=>row.map(v=>v.toFixed(6).padStart(12)).join(' ')).join('\n')}</pre>`).join('')}<p>Coordinates are in millimetres. Different sweeps have different local frames; anatomical LPS alignment and subject/phantom independence have not been verified. A visual difference between calibrations is not an independently measured calibration error.</p>`;
 else html=`<h2>Data with a traceable source.</h2><p>The bundled cases are real SonoBox research outputs dated 21 October 2026. Source acquisition hashes, original frame indices, poses, pixel spacing, checkpoint hash and STL hashes are included in the downloadable manifest.</p><h3>Sweep ${d.id}</h3><p>${d.source_frames} acquired frames · ${d.eligible_frames} usable · 64 available for display and browser reconstruction. Original indices ${d.first_eligible_index}–${d.last_eligible_index}. Frames 0–99 are excluded only in 192514.</p><p>The full-sweep STLs retain their original physical coordinates and are not decimated or recentered in the downloaded files. STL itself contains no unit metadata; these bundled exports use millimetres.</p><div class="dialog-downloads">${['matrix_1','matrix_2'].map(key=>`<a href="${d.meshes[key].file}" download="SonoBox_${d.id}_${key}.stl">${matrixName(key)} STL · ${d.meshes[key].triangles.toLocaleString('en-US')} triangles</a>`).join('')}<a href="assets/datasets.json" download="SonoBox_web_demo_manifest.json">Source &amp; calibration manifest</a></div><h3>Snapshot and limits</h3><p>The selected raw-B-mode model achieved micro foreground Dice 0.8290 on the 68 existing annotated frames of 192840. This is a historical 2D result on a previously inspected recording, not an accuracy estimate for every displayed frame or a validation of 3D geometry. Further annotation and acquisition-grouped retraining are pending.</p><p>Predictions, tracked placement and meshes are reproducible research artifacts. Source annotations, full volumes, checkpoints and identifying local filesystem paths are not bundled here. Local STL files are read in your browser and are never submitted to a server by this app.</p><h3>Selected checkpoint</h3><code>${d.checkpoint_sha256}</code>`;
 $('dialog-content').innerHTML=html;
 if(kind==='data'&&state.previewStats){const section=document.createElement('div'),button=document.createElement('button');section.className='dialog-downloads';button.className='button secondary';button.textContent='Download browser-preview provenance';button.addEventListener('click',exportPreviewMetadata);section.append(button);$('dialog-content').append(section);}
 ui.dialog.open();}

function setViewerFocus(expanded){
 const button=$('focus-viewer');
 $('workspace').classList.toggle('viewer-focused',expanded);
 $('settings-toggle').disabled=expanded;
 button.setAttribute('aria-expanded',String(expanded));
 button.setAttribute('aria-label',expanded?'Restore workspace':'Expand 3D viewer');
 button.title=button.getAttribute('aria-label');
 button.querySelector('use').setAttribute('href',expanded?'#i-collapse':'#i-expand');
 if(expanded){pause();$('viewer-panel').scrollIntoView({block:'start',behavior:'instant'});}
 else button.focus({preventScroll:true});
}

function setSettingsOpen(open){
 $('workspace').classList.toggle('settings-open',open);
 $('settings-toggle').setAttribute('aria-expanded',String(open));
 $('settings-toggle').setAttribute('aria-label',open?'Hide reconstruction settings':'Show reconstruction settings');
}

function wireEvents(){
 document.querySelectorAll('svg').forEach(icon=>icon.setAttribute('aria-hidden','true'));
 $('focus-viewer').addEventListener('click',()=>setViewerFocus($('focus-viewer').getAttribute('aria-expanded')!=='true'));
 $('settings-toggle').addEventListener('click',()=>setSettingsOpen($('settings-toggle').getAttribute('aria-expanded')!=='true'));
 document.addEventListener('keydown',event=>{
  if(event.key!=='Escape'||$('details-dialog').open)return;
  if($('workspace').classList.contains('viewer-focused')){event.preventDefault();setViewerFocus(false);}
  else if(matchMedia('(max-width:760px)').matches&&$('workspace').classList.contains('settings-open')){event.preventDefault();setSettingsOpen(false);$('settings-toggle').focus();}
 });
 for(const [id,step]of [['previous-frame',-1],['next-frame',1]])$(id).addEventListener('click',()=>{if(!state.dataset||state.mode==='custom')return;pause();state.frame=Math.max(0,Math.min(63,state.frame+step));updateFrame();});
 const oblique=document.createElement('button');oblique.textContent='3D';oblique.dataset.view='oblique';oblique.title='Oblique view';oblique.setAttribute('aria-label','Oblique view');document.querySelector('.view-toolbar [data-view="front"]').before(oblique);
 document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>selectCase(b.dataset.case).catch(e=>toast(e.message,true))));
 document.querySelectorAll('[data-matrix]').forEach(b=>b.addEventListener('click',()=>selectMatrix(b.dataset.matrix).catch(e=>toast(e.message,true))));
 document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>fitCamera(b.dataset.view)));
 for(const id of ['show-surface','show-points','show-plane','show-path','wireframe','opacity'])$(id).addEventListener('input',updateVisibility);
 $('threshold').addEventListener('input',()=>{state.threshold=Number($('threshold').value);$('threshold-value').textContent=state.threshold.toFixed(2);updateFrame();cancelAnimationFrame(state.thresholdFrame);state.thresholdFrame=requestAnimationFrame(()=>{if(state.mode!=='custom')buildClouds();});});
 $('show-overlay').addEventListener('change',updateFrame);$('frame-slider').addEventListener('input',()=>{pause();state.frame=Number($('frame-slider').value);updateFrame();});
 $('fit-camera').addEventListener('click',()=>fitCamera());$('auto-rotate').addEventListener('click',()=>{if(!controls)return;controls.autoRotate=!controls.autoRotate;$('auto-rotate').setAttribute('aria-pressed',String(controls.autoRotate));});
 $('capture').addEventListener('click',()=>{if(!renderer)return;renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(blob)saveBlob(blob,`SonoBox_${state.dataset.id}_${state.mode}.png`);});});
 $('play-pause').addEventListener('click',()=>{if(state.mode==='custom'){toast('Select an ultrasound sweep to play its frames.');return;}if(state.playing)pause();else{state.playing=true;$('play-pause').setAttribute('aria-label','Pause sweep');$('play-pause').innerHTML='<svg aria-hidden="true" viewBox="0 0 24 24"><path d="M8 5v14M16 5v14" stroke-width="4"/></svg>';}});
 $('reconstruct').addEventListener('click',reconstruct);$('cancel-reconstruction').addEventListener('click',()=>cancelReconstruction());$('restore-full').addEventListener('click',()=>restoreFull());
 $('open-stl').addEventListener('click',()=>$('stl-input').click());$('stl-input').addEventListener('change',()=>{openSTL($('stl-input').files[0]);$('stl-input').value='';});
 let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();dragDepth++;$('drop-target').hidden=false;}});document.addEventListener('dragleave',()=>{dragDepth=Math.max(0,dragDepth-1);if(dragDepth===0)$('drop-target').hidden=true;});document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.dataTransfer?.files.length){e.preventDefault();dragDepth=0;$('drop-target').hidden=true;openSTL(e.dataTransfer.files[0]);}});
 for(const id of ['method-nav','method-more'])$(id).addEventListener('click',()=>openDetails('method'));for(const id of ['data-nav','provenance-link'])$(id).addEventListener('click',()=>openDetails('data'));$('matrix-info').addEventListener('click',()=>openDetails('matrices'));$('close-dialog').addEventListener('click',()=>ui.dialog.close());$('details-dialog').addEventListener('click',e=>{if(e.target===$('details-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)ui.dialog.close();}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});
 window.addEventListener('pagehide',()=>{state.worker?.terminate();cancelAnimationFrame(animationId);resizeObserver?.disconnect();if(objectURL)URL.revokeObjectURL(objectURL);});
}

async function init(){ui=installAppleUI({onAppearance:applySceneAppearance});setupRenderer();applySceneAppearance(ui.theme);wireEvents();try{const response=await fetch('./assets/datasets.json');if(!response.ok)throw Error('The source manifest could not be loaded.');manifest=await response.json();await selectCase('192514');updateDownload();document.body.dataset.ready='true';}catch(e){showLoading(false);toast(e.message,true);document.body.dataset.ready='error';}}
init();
